import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if response.status_code != 200:
        raise Exception("Failed to access URL or invalid URL")
    data = json.loads(response.text)
    df = pd.DataFrame(data)
    if df.empty:
        raise Exception("Empty data received")
    numerical_df = df.select_dtypes(include=['number'])
    if numerical_df.empty:
        raise Exception("No numerical data for correlation")
    ax = sns.heatmap(numerical_df.corr(), annot=True)
    return df, ax

