import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError(f"File {file_path} does not exist.")
    with open(file_path, 'r') as f:
        data = json.load(f)
    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")
    for key, schema in INPUT_JSON["properties"].items():
        if key in data:
            if not isinstance(data[key], schema["type"]):
                raise ValueError(f"Invalid type for {key}. Expected {schema['type']}.")
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format.")
    return data[attribute]

import re
import json
import os
def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
        content = str(data)
        matches = re.findall(regex_pattern, content)
        filename = os.path.basename(file_path)
        return {filename: matches}
    except json.JSONDecodeError:
        filename = os.path.basename(file_path)
        return {filename: []}

