import pandas as pd
def task_func(json_str):
    try:
        data_dict = json.loads(json_str)
    except:
        return pd.DataFrame()
    normalized_dict = {}
    for key, value in data_dict.items():
        if isinstance(value, (int, float)):
            normalized_dict[key] = value * 2
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(item * 2)
                elif isinstance(item, str) and re.match(r'^-?\d+(?:\.\d+)?$', item):
                    new_list.append(float(item) * 2)
                else:
                    new_list.append(item)
            normalized_dict[key] = new_list
        elif isinstance(value, str) and re.match(r'^-?\d+(?:\.\d+)?$', value):
            normalized_dict[key] = float(value) * 2
        else:
            normalized_dict[key] = value
    return pd.DataFrame(normalized_dict)

import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    with open(input_file, 'r') as f:
        data = json.load(f)

    stats = defaultdict(list)
    for d in data:
        for key, value in d.items():
            if isinstance(value, (int, float)):
                stats[key].append(value)

    result = {}
    for key, values in stats.items():
        result[key] = {'mean': np.mean(values), 'median': np.median(values)}

    df = pd.DataFrame.from_dict(result, orient='index')
    df = df.sort_index()
    return df

import json
from glob import glob
def task_func(directory, string):
    json_files = glob(directory + '/**/*.json', recursive=True)
    result = []
    for file_path in json_files:
        with open(file_path, 'r') as f:
            try:
                data = json.load(f)
                if any(string in str(value) for value in data.values()):
                    result.append(file_path)
            except json.JSONDecodeError:
                continue
    return result

